"""Independent read-only actual Blender snapshots for the #18 technical review."""
from pathlib import Path
import sys
import json
import hashlib
import bpy


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False,
                                    allow_nan=False).encode()).hexdigest()


def simple(value):
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, bpy.types.ID):
        return {"id_type": value.bl_rna.identifier, "name": value.name}
    try:
        return [simple(item) for item in value]
    except TypeError:
        return repr(value)


def properties(value):
    result = {}
    for prop in value.bl_rna.properties:
        if prop.identifier in ("rna_type", "node_tree", "internal_links", "inputs", "outputs",
                               "users", "session_uid", "is_updated", "is_updated_data", "original",
                               "tag", "is_runtime_data", "is_embedded_data", "is_evaluated"):
            continue
        if prop.type not in ("BOOLEAN", "INT", "FLOAT", "STRING", "ENUM", "POINTER"):
            continue
        try:
            result[prop.identifier] = simple(getattr(value, prop.identifier))
        except (AttributeError, TypeError, RuntimeError):
            pass
    return result


def material_state(mat):
    result = {"properties": properties(mat)}
    if mat.node_tree:
        nodes = {}
        for node in mat.node_tree.nodes:
            nodes[node.name] = {"properties": properties(node), "inputs": [], "outputs": []}
            for kind in ("inputs", "outputs"):
                for socket in getattr(node, kind):
                    nodes[node.name][kind].append({"name": socket.name, "identifier": socket.identifier,
                        "type": socket.type, "default": simple(getattr(socket, "default_value", None)),
                        "hide": socket.hide, "enabled": socket.enabled})
        result["nodes"] = nodes
        result["links"] = sorted([[link.from_node.name, link.from_socket.identifier,
                                    link.to_node.name, link.to_socket.identifier]
                                   for link in mat.node_tree.links])
    return result


def mesh_geometry(obj):
    mesh = obj.data
    return {"matrix": [list(row) for row in obj.matrix_world],
        "parent": obj.parent.name if obj.parent else None,
        "parent_inverse": [list(row) for row in obj.matrix_parent_inverse],
        "vertices": [list(v.co) for v in mesh.vertices],
        "edges": [list(e.vertices) for e in mesh.edges],
        "faces": [list(p.vertices) for p in mesh.polygons],
        "smooth": [p.use_smooth for p in mesh.polygons],
        "groups": [[g.name, g.lock_weight] for g in obj.vertex_groups],
        "weights": [[[g.group, g.weight] for g in v.groups] for v in mesh.vertices],
        "modifiers": [properties(m) for m in obj.modifiers],
        "collections": sorted(c.name for c in obj.users_collection)}


argv = sys.argv[sys.argv.index("--") + 1:]
output = Path(argv[0])
result = {"scene_path": bpy.data.filepath, "blender_version": bpy.app.version_string,
          "mesh_geometry_sha256": {}, "mesh_material_slots": {}, "eyes": {},
          "materials": {}, "nonmesh": {}, "counts": {}, "uv_sha256": {}}
eye_names = {f"FAC_{part}_{side}" for part in ("Globe", "Iris", "Pupil", "Cornea")
             for side in ("L", "R")}
for obj in bpy.context.scene.objects:
    if obj.type == "MESH":
        state = mesh_geometry(obj)
        result["mesh_geometry_sha256"][obj.name] = digest(state)
        materials = [material.name if material else None for material in obj.data.materials]
        result["mesh_material_slots"][obj.name] = materials
        result['uv_sha256'][obj.name] = digest({uv.name: [list(v.uv) for v in uv.data]
                                               for uv in obj.data.uv_layers})
        if obj.name in eye_names:
            result["eyes"][obj.name] = {"geometry": state, "material_slots": materials,
                "polygon_material_indices": [p.material_index for p in obj.data.polygons],
                "object": properties(obj), "data": properties(obj.data),
                "attributes": [{"name": a.name, "type": a.data_type, "domain": a.domain,
                                 "length": len(a.data)} for a in obj.data.attributes]}
    else:
        result["nonmesh"][obj.name] = {"type": obj.type, "matrix": [list(row) for row in obj.matrix_world],
             "parent": obj.parent.name if obj.parent else None,
             "data": properties(obj.data) if obj.data else None}
for mat in bpy.data.materials:
    result["materials"][mat.name] = material_state(mat)
result["counts"] = {"objects": len(bpy.context.scene.objects),
                    "meshes": sum(o.type == "MESH" for o in bpy.context.scene.objects),
                    "materials": len(bpy.data.materials), "armatures": len(bpy.data.armatures),
                    "actions": len(bpy.data.actions)}
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2, ensure_ascii=False, allow_nan=False) + "\n",
                  encoding="utf-8", newline="\n")
print("INDEPENDENT TECHNICAL SNAPSHOT:", str(output), result["counts"])
